[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$CatalogPath,[string]$OutputPath='ES/Output/ResourceReader/resource-catalog-duplicates.json')
$ErrorActionPreference='Stop';$catalog=Get-Content -LiteralPath $CatalogPath -Raw -Encoding UTF8|ConvertFrom-Json -ErrorAction Stop;if($catalog.catalogId -ne 'es-resource-reader.resource-catalog.v1'){throw 'Unsupported resource catalog.'}
$groups=@{};foreach($item in @($catalog.items)){if($item -and $item.sourceSha256){$hash=[string]$item.sourceSha256;if(-not $groups.ContainsKey($hash)){$groups[$hash]=@()};$groups[$hash]+=$item}}
$duplicates=@();foreach($hash in ($groups.Keys|Sort-Object)){if($groups[$hash].Count -gt 1){$formats=@($groups[$hash]|ForEach-Object detectedFormat|Sort-Object -Unique);$statuses=@($groups[$hash]|ForEach-Object status|Sort-Object -Unique);$duplicates+=[ordered]@{sourceSha256=$hash;count=$groups[$hash].Count;sourceCount=@($groups[$hash]|ForEach-Object sourceId|Sort-Object -Unique).Count;formats=$formats;statuses=$statuses;conflict=($formats.Count -gt 1 -or $statuses.Count -gt 1);items=@($groups[$hash]|Sort-Object globalKey)}}}
$out=[ordered]@{schemaVersion=1;analysisId='es-resource-reader.catalog-duplicates.v1';catalogPath=(Resolve-Path $CatalogPath).Path;capturedUtc=[DateTime]::UtcNow.ToString('o');duplicateHashCount=$duplicates.Count;conflictCount=@($duplicates|Where-Object conflict).Count;groups=$duplicates;nonClaims=@('semantic equivalence beyond byte hash','Unity import','runtime loading','release readiness')};$dest=Join-Path (Resolve-Path '.').Path $OutputPath;New-Item -ItemType Directory -Force -Path (Split-Path -Parent $dest)|Out-Null;[IO.File]::WriteAllText($dest,($out|ConvertTo-Json -Depth 16),(New-Object Text.UTF8Encoding($false)));$out|ConvertTo-Json -Depth 16
